CARDIO.register({"item":"p159","meta":{"num":"p159","label":"159","spe":"pneumo","short":"Tuberculose","title":"Tuberculose de l'adulte","section":"P","chapter":4,"pages":"49-68","sdd":[]},"objectives":[{"id":"p159-obj-01","rank":"A","rubric":"Prévalence, épidémiologie","title":"Connaître les caractéristiques épidémiologiques de la tuberculose","desc":""},{"id":"p159-obj-02","rank":"A","rubric":"Définition","title":"Connaître la définition de la tuberculose et les caractéristiques microbiologiques des mycobactéries","desc":""},{"id":"p159-obj-03","rank":"A","rubric":"Étiologies","title":"Connaître les facteurs de risque de la tuberculose","desc":""},{"id":"p159-obj-04","rank":"A","rubric":"Éléments physiopathologiques","title":"Connaître les différentes modalités évolutives de la tuberculose","desc":""},{"id":"p159-obj-05","rank":"A","rubric":"Diagnostic positif (examen clinique, démarche diagnostique)","title":"Connaître l'indication d'une IDR à la tuberculine, d'un test IGRA","desc":""},{"id":"p159-obj-06","rank":"A","rubric":"Diagnostic positif (examen clinique, démarche diagnostique)","title":"Connaître la présentation clinique d'une primo-infection tuberculeuse","desc":""},{"id":"p159-obj-07","rank":"A","rubric":"Diagnostic positif (examen clinique, démarche diagnostique)","title":"Connaître la présentation clinique de la tuberculose pulmonaire","desc":""},{"id":"p159-obj-08","rank":"A","rubric":"Diagnostic positif","title":"Connaître la présentation clinique de la tuberculose extra-pulmonaire","desc":""},{"id":"p159-obj-09","rank":"A","rubric":"Examens complémentaires","title":"Connaître les examens complémentaires à réaliser au cours d'une tuberculose pulmonaire","desc":""},{"id":"p159-obj-10","rank":"A","rubric":"Contenu multimédia","title":"Radiographie thoracique au cours d'une tuberculose pulmonaire","desc":""},{"id":"p159-obj-11","rank":"B","rubric":"Contenu multimédia","title":"TDM thoracique au cours d'une tuberculose pulmonaire","desc":""},{"id":"p159-obj-12","rank":"A","rubric":"Prise en charge","title":"Connaître les principes généraux du traitement de la tuberculose","desc":""},{"id":"p159-obj-13","rank":"B","rubric":"Prise en charge","title":"Connaître les modalités d'administration des antituberculeux","desc":""},{"id":"p159-obj-14","rank":"A","rubric":"Prise en charge","title":"Connaître les principales caractéristiques des antituberculeux (toxicité, interactions médicamenteuses, contre-indications, surveillance, précautions d'emploi)","desc":""},{"id":"p159-obj-15","rank":"A","rubric":"Prise en charge","title":"Connaître les principes de prise en charge des sujets contacts et d'isolement du patient","desc":""},{"id":"p159-obj-16","rank":"A","rubric":"Prise en charge","title":"Savoir que la tuberculose est une maladie à déclaration obligatoire","desc":""},{"id":"p159-obj-17","rank":"A","rubric":"Prise en charge","title":"Connaître les modalités de prévention vaccinale de la tuberculose","desc":""}],"course":{"sections":[],"essentials":[],"numbers":[],"mnemonics":[]},"questions":[{"id":"p159-qroc-001","type":"QROC","rank":"A","objective":"p159-obj-01","tags":["épidémiologie"],"difficulty":1,"question":"La France est un pays de faible incidence de tuberculose. Quelle région fait exception, avec les grandes villes ?","answer":"L'Île-de-France","accept":["ile de france","idf"],"keywords":["ile"],"explanation":"La France est globalement à faible incidence (6,8 cas pour 100 000 habitants en 2020), sauf en Île-de-France et dans les grandes villes.","src":"p. 50-51"},{"id":"p159-qroc-002","type":"QROC","rank":"A","objective":"p159-obj-02","tags":["définition"],"difficulty":1,"question":"Que signifie le sigle BAAR, qui désigne le bacille de Koch à l'examen direct ?","answer":"Bacille acido-alcoolo-résistant","accept":["bacille acido alcoolo resistant","acido alcoolo resistant","bacilles acido alcoolo resistants"],"keywords":["alcool"],"explanation":"Le BK est un bacille acido-alcoolo-résistant, à croissance lente et à métabolisme aérobie strict ; on le met en évidence à l'examen direct par la coloration de Ziehl-Neelsen.","src":"p. 51, 57"},{"id":"p159-qroc-003","type":"QROC","rank":"A","objective":"p159-obj-03","tags":["étiologie"],"difficulty":1,"question":"Quelle infection est le principal facteur d'immunodépression favorisant le passage à la tuberculose maladie ?","answer":"L'infection par le VIH","accept":["vih","infection par le vih"],"keywords":["vih"],"explanation":"Parmi les causes d'immunodépression qui favorisent la tuberculose maladie (VIH, tumeurs et hémopathies, immunosuppresseurs, anti-TNF), le VIH est le facteur le plus marquant.","src":"p. 52"},{"id":"p159-qroc-004","type":"QROC","rank":"A","objective":"p159-obj-04","tags":["définition","physiopathologie"],"difficulty":1,"question":"Comment appelle-t-on, par définition, une primo-infection tuberculeuse restée asymptomatique ?","answer":"Une infection tuberculeuse latente (ITL)","accept":["itl","infection tuberculeuse latente","infection latente"],"keywords":["latente"],"explanation":"Dans l'ITL, les bacilles quiescents restent contenus dans des granulomes ; la tuberculose maladie peut toutefois survenir à n'importe quel moment.","src":"p. 51"},{"id":"p159-qroc-005","type":"QROC","rank":"A","objective":"p159-obj-04","tags":["physiopathologie"],"difficulty":1,"question":"Dans quel délai suivant la primo-infection la tuberculose maladie survient-elle le plus souvent ?","answer":"Dans les 2 premières années","accept":["2 ans","2 premieres annees","deux ans","deux premieres annees"],"keywords":["2 an"],"explanation":"Le passage de l'ITL à la tuberculose maladie est possible à tout moment mais survient surtout dans les 2 ans après la primo-infection ; le risque est accru aux âges extrêmes et en cas d'immunodépression.","src":"p. 50-51"},{"id":"p159-qroc-006","type":"QROC","rank":"A","objective":"p159-obj-04","tags":["épidémiologie","physiopathologie"],"difficulty":1,"question":"Quelle proportion des sujets ayant fait une primo-infection tuberculeuse développera une tuberculose maladie ?","answer":"Environ 10 %","accept":["10","10 pour cent","dix pour cent"],"keywords":["10"],"explanation":"Environ un primo-infecté sur dix évolue vers la tuberculose maladie, le plus souvent au cours des deux premières années après la contamination.","src":"p. 51"},{"id":"p159-qroc-007","type":"QROC","rank":"A","objective":"p159-obj-04","tags":["physiopathologie","diagnostic"],"difficulty":1,"question":"Quelle lésion histologique, fortement évocatrice mais non pathognomonique, retrouve-t-on dans les foyers tuberculeux ?","answer":"Un granulome épithélioïde giganto-cellulaire avec nécrose caséeuse","accept":["granulome epithelioide giganto cellulaire","granulome giganto cellulaire","necrose caseuse","granulome avec necrose caseuse"],"keywords":["case"],"explanation":"Ce granulome à centre nécrotique caséeux évoque fortement la tuberculose sans l'affirmer ; on y cherche les BAAR par des colorations spécifiques.","src":"p. 51, 58"},{"id":"p159-qroc-008","type":"QROC","rank":"A","objective":"p159-obj-05","tags":["diagnostic"],"difficulty":1,"question":"Combien de temps après l'injection lit-on une IDR à la tuberculine ?","answer":"72 heures","accept":["72 h","72h","3 jours","trois jours"],"keywords":["72"],"explanation":"On injecte 0,1 mL de tuberculine par voie intradermique et on lit à 72 h en mesurant l'induration autour du point de ponction, sans tenir compte de l'érythème.","src":"p. 62"},{"id":"p159-qroc-009","type":"QROC","rank":"A","objective":"p159-obj-05","tags":["diagnostic"],"difficulty":1,"question":"À partir de quel diamètre d'induration (en mm) une IDR à la tuberculine est-elle dite positive ?","answer":"5 mm","accept":["5 mm","5","cinq mm"],"keywords":["5"],"explanation":"L'IDR est négative sous 5 mm et positive à partir de 5 mm ; ce seuil ne suffit pas à suspecter une ITL, dont les seuils sont plus élevés (10 mm sans BCG, 15 mm avec BCG).","src":"p. 62"},{"id":"p159-qroc-010","type":"QROC","rank":"A","objective":"p159-obj-05","tags":["diagnostic"],"difficulty":2,"question":"Pour suspecter une ITL, quel diamètre d'induration l'IDR doit-elle dépasser chez un sujet non vacciné par le BCG, puis chez un sujet vacciné ?","answer":"10 mm (non vacciné), 15 mm (vacciné)","accept":["10 mm 15 mm","10 15 mm","10 et 15 mm","10 mm et 15 mm","10 mm puis 15 mm"],"keywords":["10","15"],"explanation":"Une induration au-delà de 10 mm chez un sujet jamais vacciné, ou de 15 mm chez un sujet vacciné, fait suspecter une ITL ; un virage tuberculinique (hausse de plus de 10 mm entre deux IDR espacées de 3 mois) est un autre argument.","src":"p. 62"},{"id":"p159-qroc-011","type":"QROC","rank":"A","objective":"p159-obj-05","tags":["diagnostic","biologie"],"difficulty":1,"question":"Quelle substance, produite par les lymphocytes en présence d'antigènes spécifiques de M. tuberculosis, mesure-t-on avec un test IGRA ?","answer":"L'interféron gamma (IFN-γ)","accept":["interferon gamma","interferon","ifn gamma","ifn"],"keywords":["interferon"],"explanation":"Le test IGRA (QuantiFERON-TB Gold IT ou T-SPOT.TB) repose sur la production d'interféron γ par les lymphocytes du sujet ; il s'agit d'une simple prise de sang, non opérateur-dépendante.","src":"p. 63"},{"id":"p159-qroc-012","type":"QROC","rank":"A","objective":"p159-obj-05","tags":["diagnostic"],"difficulty":2,"question":"Quel avantage les tests IGRA ont-ils sur l'IDR vis-à-vis du vaccin BCG ?","answer":"Pas de réaction croisée avec le BCG (moins de faux positifs)","accept":["pas de reaction croisee","ne croise pas avec le bcg","pas de croisement avec le bcg","moins de faux positifs"],"keywords":["bcg","croi"],"explanation":"L'IDR réagit aussi aux antigènes de M. bovis (donc du BCG) et de certaines mycobactéries atypiques ; l'IGRA, qui ne croise pas avec le BCG, donne moins de faux positifs.","src":"p. 62-63"},{"id":"p159-qroc-013","type":"QROC","rank":"A","objective":"p159-obj-06","tags":["clinique"],"difficulty":1,"question":"Quelle lésion cutanée peut accompagner une primo-infection tuberculeuse patente ?","answer":"L'érythème noueux","accept":["erytheme noueux","noueux"],"keywords":["noueux"],"explanation":"Une primo-infection patente associe parfois une AEG, un érythème noueux, une kérato-conjonctivite phlycténulaire et des adénopathies cervicales ; la radiographie peut montrer des adénopathies médiastinales, avec ou sans foyer primaire.","src":"p. 51"},{"id":"p159-qroc-014","type":"QROC","rank":"A","objective":"p159-obj-07","tags":["clinique"],"difficulty":1,"question":"Que retrouve-t-on généralement à l'examen physique d'une tuberculose pulmonaire commune ?","answer":"Rien : les signes physiques sont généralement absents","accept":["rien","pas de signe","aucun signe","examen normal","absents"],"keywords":["absen"],"explanation":"L'examen est pauvre ; un syndrome pleural n'apparaît qu'en cas de pleurésie tuberculeuse associée. Le diagnostic repose donc sur le contexte, la radiographie et les prélèvements.","src":"p. 53"},{"id":"p159-qroc-015","type":"QROC","rank":"A","objective":"p159-obj-07","tags":["clinique","diagnostic"],"difficulty":2,"question":"Chez un patient VIH avec moins de 200 CD4/mm³, quel signe est souvent le seul présent en cas de tuberculose ?","answer":"La fièvre","accept":["fievre","fievre prolongee"],"keywords":["fievre"],"explanation":"Plus l'immunodépression est profonde, moins les symptômes sont marqués : on pense à la tuberculose devant une fièvre prolongée, on cherche systématiquement des atteintes extra-respiratoires, et la radiographie peut être quasi normale.","src":"p. 65"},{"id":"p159-qroc-016","type":"QROC","rank":"A","objective":"p159-obj-08","tags":["physiopathologie","clinique"],"difficulty":1,"question":"Par quelle voie le bacille de Koch se dissémine-t-il dans la miliaire tuberculeuse ?","answer":"Par voie hématogène","accept":["hematogene","voie hematogene","sang","voie sanguine"],"keywords":["hematogen"],"explanation":"La miliaire est une forme disséminée par voie hématogène (bacillémie initiale ou érosion vasculaire à partir d'un foyer caséeux) ; elle touche le poumon et de nombreux autres organes, d'où sa sévérité.","src":"p. 55"},{"id":"p159-qroc-017","type":"QROC","rank":"A","objective":"p159-obj-08","tags":["clinique","diagnostic"],"difficulty":2,"question":"Quelle est la nature du liquide d'une pleurésie tuberculeuse ?","answer":"Un exsudat lymphocytaire à liquide clair","accept":["exsudat lymphocytaire","lymphocytaire","exsudat a predominance lymphocytaire"],"keywords":["lymphocyt"],"explanation":"La pleurésie tuberculeuse vient de l'effraction d'un foyer sous-pleural souvent invisible à la radiographie ; la biopsie pleurale (histologie et culture) est plus rentable que le liquide, et la PCR est rarement positive.","src":"p. 55-56"},{"id":"p159-qroc-018","type":"QROC","rank":"A","objective":"p159-obj-09","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Sur un crachat, quelle recherche faut-il demander spécifiquement car elle n'est pas faite lors d'un ECBC standard ?","answer":"La recherche de BAAR (mycobactéries)","accept":["baar","recherche de baar","bacilles acido alcoolo resistants","mycobacteries","bk","bacille de koch"],"keywords":["baar"],"explanation":"Un ECBC standard ne cherche pas les BAAR : il faut demander l'examen direct puis la culture, adressés au laboratoire de mycobactériologie ; les prélèvements sont toujours multiples et répétés.","src":"p. 56"},{"id":"p159-qroc-019","type":"QROC","rank":"A","objective":"p159-obj-09","tags":["diagnostic","paraclinique"],"difficulty":1,"question":"Chez un patient suspect de tuberculose pulmonaire qui ne crache pas, quel prélèvement réalise-t-on ?","answer":"Un tubage gastrique (le matin à jeun, avant le lever)","accept":["tubage gastrique","tubage"],"keywords":["tubage"],"explanation":"Les sécrétions sont avalées pendant la nuit et les BAAR résistent à l'acidité gastrique : on prélève le matin à jeun avant tout lever, avant la vidange gastrique.","src":"p. 56"},{"id":"p159-qroc-020","type":"QROC","rank":"A","objective":"p159-obj-09","tags":["diagnostic","paraclinique"],"difficulty":2,"question":"Après trois prélèvements négatifs à l'examen direct, ou devant une suspicion de miliaire, quel examen endoscopique réalise-t-on ?","answer":"Une fibroscopie bronchique avec aspiration","accept":["fibroscopie bronchique","fibroscopie","endoscopie bronchique","bronchoscopie"],"keywords":["fibro"],"explanation":"En cas d'échec des prélèvements usuels, on aspire les sécrétions dans un territoire atteint d'après l'imagerie.","src":"p. 57"},{"id":"p159-qroc-021","type":"QROC","rank":"A","objective":"p159-obj-09","tags":["diagnostic","biologie"],"difficulty":1,"question":"Quel examen bactériologique est systématique même lorsque l'examen direct est négatif ?","answer":"La culture sur milieux enrichis","accept":["culture","mise en culture","culture sur milieu enrichi"],"keywords":["cultur"],"explanation":"L'examen direct n'est positif qu'au-delà de 10³ bacilles/mL : sa négativité n'élimine pas la tuberculose. La culture est positive en 3 à 4 semaines sur milieu solide (Löwenstein-Jensen) et en 10 à 15 jours environ sur milieu liquide.","src":"p. 57"},{"id":"p159-qroc-022","type":"QROC","rank":"A","objective":"p159-obj-09","tags":["diagnostic","biologie"],"difficulty":2,"question":"La recherche de mutations du gène rpoB par un test génotypique détecte la résistance à quel antituberculeux ?","answer":"La rifampicine","accept":["rifampicine","rmp","rifampicin"],"keywords":["rifamp"],"explanation":"Tout examen direct ou toute culture positifs doit être complété rapidement par un test génotypique (résultat sous 72 h au plus) : il confirme une mycobactérie du complexe tuberculosis et cherche les mutations du gène rpoB (rifampicine), couplées si possible à celles de l'isoniazide.","src":"p. 57"},{"id":"p159-qroc-023","type":"QROC","rank":"A","objective":"p159-obj-10","tags":["imagerie"],"difficulty":1,"question":"Quels sont les trois types de lésions radiologiques de la tuberculose pulmonaire commune ?","answer":"Nodules, infiltrats et cavernes","accept":["nodules infiltrats cavernes","nodules infiltrats et cavernes","nodules infiltrats caverne","nodules infiltrats lesions excavees"],"keywords":["nodul","infiltr","cavern"],"explanation":"Ces lésions, isolées ou associées, siègent généralement dans les segments supérieurs et postérieurs des poumons.","src":"p. 53"},{"id":"p159-qroc-024","type":"QROC","rank":"A","objective":"p159-obj-10","tags":["imagerie"],"difficulty":1,"question":"Dans quels segments pulmonaires siègent généralement les lésions de la tuberculose pulmonaire commune ?","answer":"Les segments supérieurs et postérieurs","accept":["segments superieurs et posterieurs","superieurs et posterieurs","lobes superieurs","lobe superieur","apex"],"keywords":["superieur"],"explanation":"On évoque la tuberculose devant des infiltrats, des nodules ou des cavernes des lobes supérieurs, dans leurs segments supérieurs et postérieurs.","src":"p. 50, 53"},{"id":"p159-qroc-025","type":"QROC","rank":"A","objective":"p159-obj-12","tags":["traitement"],"difficulty":1,"question":"Quelle est la durée totale du traitement standard d'une tuberculose multisensible (hors forme neuro-méningée) ?","answer":"6 mois","accept":["6 mois","six mois"],"keywords":["6 mois"],"explanation":"Le schéma classique comporte 2 mois de quadrithérapie (INH + RMP + EMB + PZA) puis 4 mois de bithérapie (INH + RMP) ; ces 6 mois valent pour toutes les formes multisensibles sauf la forme neuro-méningée.","src":"p. 50, 60"},{"id":"p159-qroc-026","type":"QROC","rank":"A","objective":"p159-obj-12","tags":["traitement"],"difficulty":1,"question":"Quelle bithérapie fait suite aux 2 premiers mois de quadrithérapie dans le schéma classique ?","answer":"Isoniazide + rifampicine (INH + RMP), 4 mois","accept":["inh rmp","rmp inh","inh et rmp","rmp et inh","isoniazide et rifampicine","rifampicine et isoniazide"],"keywords":["isoniaz","rifamp"],"explanation":"La phase d'entretien associe INH et RMP pendant 4 mois, souvent sous la forme de l'association fixe Rifinah®.","src":"p. 59-60"},{"id":"p159-qroc-027","type":"QROC","rank":"A","objective":"p159-obj-12","tags":["traitement"],"difficulty":1,"question":"Quels deux antituberculeux s'ajoutent à l'isoniazide et à la rifampicine pendant les 2 premiers mois ?","answer":"Éthambutol (EMB) et pyrazinamide (PZA)","accept":["emb pza","pza emb","emb et pza","pza et emb","ethambutol et pyrazinamide","pyrazinamide et ethambutol"],"keywords":["ethamb","pyrazin"],"explanation":"La phase d'attaque est une quadrithérapie INH + RMP + EMB + PZA de 2 mois (souvent Rifater® + EMB).","src":"p. 60"},{"id":"p159-qroc-028","type":"QROC","rank":"A","objective":"p159-obj-12","tags":["traitement"],"difficulty":2,"question":"Quelle seule forme de tuberculose multisensible impose un traitement plus long, de 9 à 12 mois ?","answer":"La tuberculose neuro-méningée","accept":["neuro meningee","tuberculose meningee","meningite tuberculeuse","meningee"],"keywords":["mening"],"explanation":"Toutes les autres formes de tuberculose multisensible sont traitées 6 mois ; seule la forme neuro-méningée l'est systématiquement 9 à 12 mois.","src":"p. 60"},{"id":"p159-qroc-029","type":"QROC","rank":"B","objective":"p159-obj-13","tags":["traitement"],"difficulty":1,"question":"Comment doit être prise la rifampicine par rapport aux repas ?","answer":"À jeun, à distance des repas (30 min à 1 h avant, ≥ 2 h après)","accept":["a jeun","loin des repas","avant le repas","a distance des repas"],"keywords":["jeun"],"explanation":"L'alimentation réduit l'absorption de la RMP, d'où une prise quotidienne unique à distance des repas (avant : 30 min à 1 h ; après : au moins 2 h).","src":"p. 60"},{"id":"p159-qroc-030","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement"],"difficulty":1,"question":"Quel antituberculeux est un puissant inducteur enzymatique ?","answer":"La rifampicine (RMP)","accept":["rifampicine","rmp","rifampicin"],"keywords":["rifamp"],"explanation":"La RMP expose à de nombreuses interactions : AVK (surveillance de l'INR) et anticoagulants oraux directs, pilule œstro-progestative, certains antirétroviraux, méthadone, corticoïdes, digitaliques.","src":"p. 59"},{"id":"p159-qroc-031","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement"],"difficulty":1,"question":"Quel est l'effet de la rifampicine sur une pilule œstro-progestative ?","answer":"Elle la rend inefficace : il faut un autre moyen de contraception","accept":["inefficace","pilule inefficace","autre moyen de contraception","changer de contraception","contraception mecanique"],"keywords":["inefficac"],"explanation":"Sous rifampicine, la pilule œstro-progestative n'est plus efficace : il faut changer de mode de contraception (la contraception mécanique est la seule possible).","src":"p. 59, 61"},{"id":"p159-qroc-032","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement"],"difficulty":1,"question":"Quel phénomène normal, et non un effet indésirable, faut-il annoncer au patient traité par rifampicine ?","answer":"Une coloration orange des urines, des larmes et du sperme","accept":["orange","coloration orange"],"keywords":["orang"],"explanation":"La RMP colore en orange les larmes, le sperme et les urines : ce n'est pas un effet secondaire mais un phénomène normal, qu'il faut annoncer au patient.","src":"p. 59, 61"},{"id":"p159-qroc-033","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement","complications"],"difficulty":1,"question":"Quel est le principal effet indésirable de l'éthambutol ?","answer":"La névrite optique rétrobulbaire","accept":["nevrite optique","nevrite optique retrobulbaire","nevrite retrobulbaire"],"keywords":["nevrite","optique"],"explanation":"Elle survient surtout en cas de posologie élevée prolongée, d'éthylisme chronique ou d'insuffisance rénale ; d'où un examen ophtalmologique (vision des couleurs, champ visuel) à la mise en route puis une surveillance de la vision des couleurs.","src":"p. 59, 61"},{"id":"p159-qroc-034","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement"],"difficulty":2,"question":"Quelles sont les deux contre-indications du pyrazinamide ?","answer":"Insuffisance hépatocellulaire et insuffisance rénale","accept":["insuffisance hepatocellulaire et insuffisance renale","insuffisance hepatique et renale","hepatique et renale","renale et hepatique"],"keywords":["hepat","renal"],"explanation":"Le PZA est contre-indiqué en cas d'insuffisance hépatocellulaire et d'insuffisance rénale ; il peut provoquer une cytolyse hépatique (plus tardive que sous INH) et une hyperuricémie par effondrement de l'uraturie.","src":"p. 59"},{"id":"p159-qroc-035","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement","complications"],"difficulty":2,"question":"Quelle complication de l'isoniazide la vitamine B6 (pyridoxine) permet-elle de prévenir ?","answer":"La polynévrite (polyneuropathie) sensitivo-motrice","accept":["polynevrite","polyneuropathie","polynevrite sensitivo motrice"],"keywords":["polyn"],"explanation":"La carence en vitamine B6 favorise la polyneuropathie sous INH ; la pyridoxine est prescrite surtout en cas de grossesse, d'alcoolisme chronique ou de dénutrition.","src":"p. 59-60"},{"id":"p159-qroc-036","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement","suivi"],"difficulty":2,"question":"Sous quadrithérapie, les transaminases sont entre 3 et 5 N : quel antituberculeux arrête-t-on ?","answer":"Le pyrazinamide (PZA)","accept":["pyrazinamide","pza"],"keywords":["pyrazin"],"explanation":"De 3 à 5 N, on stoppe le PZA mais on garde INH + RMP + EMB (2 mois), puis INH + RMP (7 mois). Au-delà de 5 N : arrêt de l'INH et du PZA.","src":"p. 61"},{"id":"p159-qroc-037","type":"QROC","rank":"A","objective":"p159-obj-14","tags":["traitement","pièges"],"difficulty":2,"question":"Quelle classe d'antibiotiques faut-il éviter devant une infection pulmonaire pouvant être tuberculeuse, car elle risque de négativer les prélèvements ?","answer":"Les fluoroquinolones","accept":["fluoroquinolone","fluoroquinolones","quinolones"],"keywords":["quinolone"],"explanation":"Les fluoroquinolones sont réservées à la tuberculose résistante documentée ; les prescrire d'emblée devant une pneumonie suspecte peut négativer les prélèvements.","src":"p. 59-60"},{"id":"p159-qroc-038","type":"QROC","rank":"A","objective":"p159-obj-15","tags":["prévention"],"difficulty":1,"question":"Depuis combien de temps un patient contagieux au moment du diagnostic l'est-il en général déjà ?","answer":"3 mois","accept":["3 mois","trois mois"],"keywords":["3 mois"],"explanation":"Il a donc pu contaminer son entourage proche : la période de contagiosité retenue pour l'enquête autour du cas couvre les 3 mois précédant le diagnostic.","src":"p. 61-62"},{"id":"p159-qroc-039","type":"QROC","rank":"A","objective":"p159-obj-15","tags":["prévention"],"difficulty":1,"question":"Si l'examen direct est négatif au départ, après combien de temps de traitement complet lève-t-on en général l'isolement respiratoire ?","answer":"15 jours","accept":["15 jours","15 j","2 semaines","deux semaines"],"keywords":["15 j"],"explanation":"L'isolement peut être prolongé si la tuberculose était très bacillifère ou si des enfants, des personnes âgées ou des immunodéprimés vivent au domicile.","src":"p. 61"},{"id":"p159-qroc-040","type":"QROC","rank":"A","objective":"p159-obj-15","tags":["prévention"],"difficulty":1,"question":"Quelle structure reçoit le signalement nominatif d'un cas de tuberculose et mène l'enquête autour du cas ?","answer":"Le CLAT (Centre de lutte antituberculeuse)","accept":["clat","centre de lutte anti tuberculeuse","centre de lutte antituberculeuse"],"keywords":["clat"],"explanation":"Le signalement nominatif au CLAT, fait en même temps que la déclaration anonyme à l'ARS, déclenche l'enquête autour du cas ; le CLAT joue aussi un rôle fondamental dans le suivi du traitement.","src":"p. 60, 66"},{"id":"p159-qroc-041","type":"QROC","rank":"A","objective":"p159-obj-15","tags":["prévention","diagnostic"],"difficulty":2,"question":"À quel délai après le dernier contact avec le cas index réalise-t-on le test de dépistage de l'ITL (IGRA ou IDR) ?","answer":"8 semaines","accept":["8 semaines","8 sem","2 mois"],"keywords":["8 sem"],"explanation":"Dès que possible, on dépiste une éventuelle tuberculose maladie (examen clinique, évaluation des risques, radiographie thoracique) ; le test IGRA ou IDR, 8 semaines après le dernier contact, sert à diagnostiquer l'ITL.","src":"p. 66"},{"id":"p159-qroc-042","type":"QROC","rank":"A","objective":"p159-obj-16","tags":["prévention"],"difficulty":1,"question":"Auprès de quel organisme s'effectue la notification anonyme (déclaration obligatoire) d'un cas de tuberculose ?","answer":"L'ARS (Agence régionale de santé)","accept":["ars","agence regionale de sante"],"keywords":["ars"],"explanation":"La déclaration anonyme se fait sur formulaire en ligne auprès de l'ARS, qui la relaie vers Santé publique France ; le signalement nominatif au CLAT est distinct et déclenche l'enquête autour du cas.","src":"p. 66"},{"id":"p159-qroc-043","type":"QROC","rank":"A","objective":"p159-obj-16","tags":["prévention"],"difficulty":2,"question":"À partir de quel moment une tuberculose maladie suspectée doit-elle être déclarée ?","answer":"Dès le début du traitement, même sans preuve bactériologique","accept":["debut du traitement","des le debut du traitement","meme sans preuve bacteriologique"],"keywords":["debut"],"explanation":"Les tuberculoses maladie confirmées ou suspectées sont déclarées dès qu'un traitement est mis en route, même sans preuve bactériologique, afin d'identifier les sujets contaminés.","src":"p. 66"},{"id":"p159-qroc-044","type":"QROC","rank":"A","objective":"p159-obj-16","tags":["prévention","pédiatrie"],"difficulty":1,"question":"Une infection tuberculeuse latente doit être déclarée chez l'enfant et le jeune de moins de quel âge ?","answer":"18 ans","accept":["18 ans","18","dix huit ans"],"keywords":["18"],"explanation":"Seule l'ITL de l'enfant ou du jeune de moins de 18 ans est à déclarer (le seuil était de 15 ans avant 2021), afin d'identifier le sujet contaminant.","src":"p. 66"},{"id":"p159-qroc-045","type":"QROC","rank":"A","objective":"p159-obj-17","tags":["prévention"],"difficulty":1,"question":"Quelle infection, chez l'enfant ou chez sa mère, contre-indique le vaccin BCG ?","answer":"L'infection par le VIH","accept":["vih","infection par le vih"],"keywords":["vih"],"explanation":"Les autres contre-indications du BCG sont les déficits immunitaires congénitaux ou acquis, les traitements immunosuppresseurs et les dermatoses étendues évolutives.","src":"p. 64"},{"id":"p159-qru-101","type":"QRU","rank":"A","objective":"p159-obj-09","tags":["diagnostic","paraclinique"],"difficulty":1,"stem":"Un homme de 48 ans, sans domicile fixe, consulte pour une toux persistante depuis 6 semaines, avec sueurs nocturnes et amaigrissement. La radiographie thoracique montre un infiltrat et une caverne du lobe supérieur droit. Il expectore. Quelle est la démarche diagnostique adaptée ?","options":[{"t":"Recherche de BAAR et culture sur des crachats répétés","ok":true,"why":"Le diagnostic de certitude repose sur la mise en évidence du BK : prélèvements respiratoires multiples et répétés, avec recherche de BAAR demandée spécifiquement (examen direct puis culture)."},{"t":"ECBC standard, qui suffit à rechercher le bacille de Koch sur un seul prélèvement","ok":false,"why":"Faux : un ECBC standard n'inclut pas la recherche de BAAR, et un prélèvement unique ne suffit pas (prélèvements multiples et répétés)."},{"t":"IDR à la tuberculine, dont la positivité confirme la tuberculose maladie","ok":false,"why":"Faux : l'IDR, comme l'IGRA, ne distingue pas ITL et tuberculose maladie ; elle ne sert qu'au diagnostic d'ITL."},{"t":"Tubage gastrique d'emblée, même chez un patient qui crache, car il est plus rentable","ok":false,"why":"Faux : le tubage gastrique est réservé au patient qui ne crache pas."},{"t":"Test IGRA, dont la négativité permettrait d'éliminer une tuberculose maladie","ok":false,"why":"Faux : ces tests ne servent ni à diagnostiquer ni à éliminer une tuberculose active."}],"explanation":"Le diagnostic de tuberculose repose sur la mise en évidence du BK. Chez un patient qui crache : recherche de BAAR demandée spécifiquement (examen direct après Ziehl-Neelsen puis culture), prélèvements répétés adressés au laboratoire de mycobactériologie, avec isolement respiratoire s'il est hospitalisé.","trap":"Un ECBC standard ne comporte pas de recherche de BAAR.","src":"p. 56, 62-63"},{"id":"p159-qru-102","type":"QRU","rank":"A","objective":"p159-obj-05","tags":["diagnostic"],"difficulty":2,"stem":"Un patient jamais vacciné par le BCG, contact étroit d'un cas de tuberculose pulmonaire bacillifère, a une IDR à la tuberculine mesurant 12 mm d'induration pour 25 mm d'érythème à la lecture. Quelle conclusion est exacte ?","options":[{"t":"Suspicion d'ITL, après avoir éliminé une tuberculose maladie","ok":true,"why":"Sans BCG antérieur, une induration supérieure à 10 mm fait suspecter une ITL ; on élimine d'abord une tuberculose maladie (examen clinique et radiographie thoracique)."},{"t":"IDR négative, l'induration restant inférieure à 15 mm","ok":false,"why":"Faux : l'IDR est positive dès 5 mm ; le seuil de 15 mm ne concerne que les sujets vaccinés."},{"t":"Tuberculose maladie confirmée, justifiant une quadrithérapie d'emblée","ok":false,"why":"Faux : l'IDR ne distingue pas ITL et tuberculose maladie et ne confirme jamais une tuberculose active."},{"t":"Résultat à interpréter d'après l'érythème de 25 mm, qui rend l'IDR douteuse","ok":false,"why":"Faux : on mesure l'induration et on ne tient pas compte de l'érythème."},{"t":"Réaction attribuable au BCG, donc sans valeur pour le dépistage","ok":false,"why":"Faux : le patient n'a jamais été vacciné, la réaction ne peut pas être due au BCG."}],"explanation":"IDR lue à 72 h sur l'induration : négative sous 5 mm, positive à partir de 5 mm ; suspicion d'ITL au-delà de 10 mm sans BCG (15 mm si vacciné). L'IDR ne distingue pas ITL et tuberculose maladie : on élimine d'abord celle-ci par l'examen clinique et la radiographie.","src":"p. 62"},{"id":"p159-qru-103","type":"QRU","rank":"A","objective":"p159-obj-12","tags":["traitement"],"difficulty":1,"stem":"Quel est le schéma classique de traitement d'une tuberculose pulmonaire multisensible chez l'adulte ?","options":[{"t":"Quadrithérapie INH + RMP + EMB + PZA pendant 2 mois, puis INH + RMP pendant 4 mois","ok":true,"why":"Schéma classique : 2 mois de quadrithérapie puis 4 mois de bithérapie, soit 6 mois au total."},{"t":"Quadrithérapie INH + RMP + EMB + PZA pendant 2 mois, puis INH + RMP pendant 7 mois","ok":false,"why":"Faux : les 7 mois de bithérapie suivent une trithérapie sans PZA dans le schéma alternatif, pas une quadrithérapie."},{"t":"Trithérapie INH + RMP + EMB pendant 2 mois, puis INH + RMP pendant 4 mois","ok":false,"why":"Faux : la trithérapie de 2 mois correspond au schéma alternatif (contre-indication au PZA), suivie de 7 mois de bithérapie."},{"t":"Bithérapie INH + RMP pendant 6 mois d'emblée","ok":false,"why":"Faux : la phase d'attaque est une quadrithérapie de 2 mois."},{"t":"Quadrithérapie INH + RMP + EMB + PZA pendant 6 mois","ok":false,"why":"Faux : la quadrithérapie ne dure que 2 mois."}],"explanation":"Schéma classique : INH + RMP + EMB + PZA pendant 2 mois (souvent Rifater® + EMB), puis INH + RMP pendant 4 mois (souvent Rifinah®), adapté à l'antibiogramme. Le schéma alternatif (contre-indication ou effet grave du PZA) associe INH + RMP + EMB 2 mois puis INH + RMP 7 mois.","src":"p. 60"},{"id":"p159-qru-104","type":"QRU","rank":"A","objective":"p159-obj-14","tags":["traitement","complications"],"difficulty":1,"stem":"Un patient sous quadrithérapie antituberculeuse présente une hyperuricémie asymptomatique. Quel médicament est en cause ?","options":[{"t":"Le pyrazinamide","ok":true,"why":"Le PZA provoque une hyperuricémie par effondrement de l'uraturie, généralement asymptomatique (crise de goutte possible, sans risque de colique néphrétique)."},{"t":"L'isoniazide","ok":false,"why":"Faux : l'INH expose aux troubles digestifs, à l'hépatite et à la polynévrite en cas de carence en vitamine B6."},{"t":"La rifampicine","ok":false,"why":"Faux : la RMP est un inducteur enzymatique, source de réactions immuno-allergiques et de coloration orange des sécrétions."},{"t":"L'éthambutol","ok":false,"why":"Faux : son principal effet indésirable est la névrite optique rétrobulbaire."},{"t":"Aucun des quatre antituberculeux de première ligne","ok":false,"why":"Faux : le pyrazinamide est connu pour cet effet."}],"explanation":"Chaque antituberculeux a sa toxicité propre : INH (hépatite, polynévrite), RMP (inducteur enzymatique, coloration orange), EMB (névrite optique), PZA (cytolyse hépatique tardive, hyperuricémie).","src":"p. 59"},{"id":"p159-qru-105","type":"QRU","rank":"A","objective":"p159-obj-15","tags":["prévention","suivi"],"difficulty":2,"stem":"Un patient de 40 ans est hospitalisé pour une tuberculose pulmonaire dont l'examen direct initial est négatif ; il reçoit un traitement standard bien conduit. À partir de quand peut-on en général lever l'isolement respiratoire ?","options":[{"t":"Après 15 jours de traitement complet","ok":true,"why":"Lorsque les examens directs sont négatifs au départ, on lève en général l'isolement après 15 jours de traitement plein."},{"t":"Dès le début du traitement, puisque l'examen direct est négatif","ok":false,"why":"Faux : un examen direct négatif n'élimine pas la tuberculose ; on attend 15 jours de traitement plein."},{"t":"Après 1 mois de traitement","ok":false,"why":"Faux : le délai habituel est de 15 jours."},{"t":"Après 2 mois, à la fin de la phase d'attaque","ok":false,"why":"Faux : le délai habituel est de 15 jours."},{"t":"À la fin des 6 mois de traitement","ok":false,"why":"Faux : l'isolement ne dure pas jusqu'à la fin du traitement."}],"explanation":"Le patient hospitalisé est mis en chambre seule en isolement respiratoire avant les prélèvements. Si les examens directs sont négatifs au départ, on lève l'isolement après 15 jours de traitement plein ; il est prolongé si la tuberculose était très bacillifère ou si des enfants, des personnes âgées ou des immunodéprimés vivent au domicile.","src":"p. 56, 61"},{"id":"p159-qru-106","type":"QRU","rank":"A","objective":"p159-obj-16","tags":["prévention"],"difficulty":2,"stem":"Concernant la déclaration de la tuberculose, quelle proposition est exacte ?","options":[{"t":"Notification anonyme à l'ARS et signalement nominatif au CLAT","ok":true,"why":"La notification anonyme (déclaration obligatoire) va à l'ARS puis à Santé publique France ; le signalement nominatif, fait par tout moyen auprès du CLAT, déclenche l'enquête autour du cas."},{"t":"Déclaration à faire uniquement une fois le diagnostic confirmé par culture","ok":false,"why":"Faux : une tuberculose suspectée est déclarée dès qu'un traitement est débuté, même sans preuve bactériologique."},{"t":"Seules les formes pulmonaires à examen direct positif sont déclarées","ok":false,"why":"Faux : toute tuberculose maladie confirmée ou suspectée est à déclarer."},{"t":"Signalement nominatif sur formulaire type en ligne auprès de l'ARS","ok":false,"why":"Faux : le signalement nominatif va au CLAT, sans formulaire type ; le formulaire en ligne concerne la notification anonyme."},{"t":"Toute infection tuberculeuse latente de l'adulte doit être déclarée","ok":false,"why":"Faux : seule l'ITL de l'enfant ou du jeune de moins de 18 ans est à déclarer."}],"explanation":"Sont à déclarer : la tuberculose maladie confirmée ou suspectée (dès qu'un traitement est débuté) et l'ITL de moins de 18 ans. Il existe aussi une déclaration anonyme des issues de traitement à 12 mois, auprès de l'ARS.","src":"p. 66"},{"id":"p159-qru-107","type":"QRU","rank":"A","objective":"p159-obj-17","tags":["prévention","pédiatrie"],"difficulty":1,"stem":"Quelle proposition concernant la vaccination par le BCG est exacte ?","options":[{"t":"Plus obligatoire, mais fortement recommandée chez l'enfant à risque","ok":true,"why":"Le BCG est fortement recommandé chez l'enfant de moins de 15 ans exposé à un risque particulier (Guyane, Mayotte, Île-de-France, lien étroit avec une zone de forte endémie, antécédents familiaux, grande précarité)."},{"t":"Obligatoire pour tout enfant à l'entrée en collectivité (crèche, école)","ok":false,"why":"Faux : le BCG n'est plus obligatoire pour les enfants et les adolescents."},{"t":"Protection définitive, sans atténuation de l'immunité avec le temps","ok":false,"why":"Faux : l'immunité conférée par le vaccin s'atténue en 10 à 15 ans."},{"t":"Précédée d'une IDR systématique chez le nourrisson avant l'injection","ok":false,"why":"Faux : il n'y a pas de test tuberculinique préalable ; il n'est contrôlé que pour une vaccination plus tardive, jusqu'à 15 ans."},{"t":"Administrée par voie sous-cutanée profonde dans la cuisse du nourrisson","ok":false,"why":"Faux : l'administration est intradermique, dans le deltoïde."}],"explanation":"Le BCG vise à limiter le risque de tuberculose neuro-méningée, de miliaire et de tuberculose pulmonaire. Il est donné le plus tôt possible (si possible à la naissance), en intradermique dans le deltoïde.","src":"p. 64"},{"id":"p159-qru-108","type":"QRU","rank":"A","objective":"p159-obj-04","tags":["définition","physiopathologie"],"difficulty":1,"stem":"Quelle proposition concernant l'infection tuberculeuse latente (ITL) est exacte ?","options":[{"t":"Une primo-infection tuberculeuse asymptomatique, par définition","ok":true,"why":"L'ITL est par définition une PIT asymptomatique, avec des bacilles quiescents contenus dans des granulomes."},{"t":"C'est une tuberculose pulmonaire excavée, mais sans aucun symptôme clinique","ok":false,"why":"Faux : une caverne relève de la tuberculose maladie ; l'ITL est une PIT asymptomatique, et l'examen clinique et la radiographie servent à éliminer d'abord la tuberculose maladie."},{"t":"Une IDR négative permet de la distinguer de la tuberculose maladie","ok":false,"why":"Faux : IDR et IGRA ne distinguent pas ITL et tuberculose maladie."},{"t":"Elle ne peut jamais évoluer vers la tuberculose maladie, même à distance","ok":false,"why":"Faux : le passage à la tuberculose maladie est possible à n'importe quel moment."},{"t":"Elle ne s'observe que chez les patients immunodéprimés ou très âgés","ok":false,"why":"Faux : l'immunodépression augmente le risque de passage à la tuberculose maladie, elle n'est pas nécessaire à l'ITL."}],"explanation":"Après la contamination, la PIT est le plus souvent asymptomatique et passe à la latence (ITL). Environ 10 % des primo-infectés font ensuite une tuberculose maladie, le plus souvent dans les 2 premières années.","src":"p. 50-51, 62"},{"id":"p159-qcm-101","type":"QRM","rank":"A","objective":"p159-obj-03","tags":["étiologie"],"difficulty":1,"stem":"Chez un sujet ayant une infection tuberculeuse latente, quelles situations favorisent le développement d'une tuberculose maladie ?","options":[{"t":"Une infection par le VIH","ok":true,"why":"Le VIH est le facteur d'immunodépression le plus marquant."},{"t":"Un traitement par anti-TNFα","ok":true,"why":"Les anti-TNF augmentent nettement l'incidence de la tuberculose."},{"t":"Un âge extrême (très jeune ou très âgé)","ok":true,"why":"Le risque de passage à la tuberculose maladie est accru aux âges extrêmes."},{"t":"Un antécédent de vaccination par le BCG","ok":false,"why":"Faux : le BCG vise à limiter le risque de formes graves, il ne favorise pas la tuberculose maladie."},{"t":"Une chimioprophylaxie par isoniazide bien conduite","ok":false,"why":"Faux : elle sert précisément à limiter le passage de l'ITL à la tuberculose maladie."}],"explanation":"Favorisent la tuberculose maladie : immunodépression (VIH, tumeurs et hémopathies, immunosuppresseurs, anti-TNF), âges extrêmes, diabète, insuffisance rénale, malnutrition, alcoolisme/tabagisme, précarité, toxicomanie.","src":"p. 52, 63-64"},{"id":"p159-qcm-102","type":"QRM","rank":"A","objective":"p159-obj-04","tags":["physiopathologie"],"difficulty":2,"stem":"Concernant l'histoire naturelle de la tuberculose, quelles propositions sont exactes ?","options":[{"t":"La contamination se fait par inhalation de gouttelettes infectantes émises à la toux par un patient bacillifère","ok":true,"why":"La transmission est aérienne ; les gouttelettes atteignent les alvéoles et forment le foyer primaire."},{"t":"La primo-infection est le plus souvent asymptomatique","ok":true,"why":"Elle est le plus souvent asymptomatique et conduit à l'ITL ; elle n'est patente que parfois."},{"t":"La tuberculose maladie survient presque toujours plus de 10 ans après la primo-infection","ok":false,"why":"Faux : elle survient surtout dans les 2 premières années."},{"t":"Le risque de contamination ne dépend que de la durée d'exposition","ok":false,"why":"Faux : il dépend aussi de l'intensité de la toux et de la contagiosité du cas (examen direct positif, cavernes)."},{"t":"L'ITL se traduit par un érythème noueux et une kérato-conjonctivite phlycténulaire","ok":false,"why":"Faux : ces signes appartiennent à la PIT patente ; l'ITL est asymptomatique par définition."}],"explanation":"Étape 1 : contamination aérienne ; étape 2 : PIT le plus souvent asymptomatique, puis ITL (granulomes à nécrose caséeuse avec bacilles quiescents) ; étape 3 : tuberculose maladie, dans 10 % des cas, surtout dans les 2 ans.","src":"p. 51"},{"id":"p159-qcm-103","type":"QRM","rank":"A","objective":"p159-obj-06","tags":["clinique"],"difficulty":2,"stem":"Un adulte de 25 ans, contact récent d'un cas de tuberculose bacillifère, présente une altération de l'état général, un érythème noueux et une kérato-conjonctivite phlycténulaire ; la radiographie thoracique montre des adénopathies médiastinales. Quelles propositions sont exactes ?","options":[{"t":"Il s'agit d'une primo-infection tuberculeuse patente","ok":true,"why":"Ce tableau est celui d'une PIT patente, avec AEG, érythème noueux et kérato-conjonctivite phlycténulaire."},{"t":"La radiographie peut aussi montrer une lésion parenchymateuse du foyer primaire (chancre d'inoculation)","ok":true,"why":"Les adénopathies médiastinales peuvent s'associer ou non à une lésion parenchymateuse correspondant au foyer primaire."},{"t":"Ce tableau est la présentation habituelle de la primo-infection, le plus souvent symptomatique","ok":false,"why":"Faux : la PIT est le plus souvent asymptomatique ; elle n'est patente que parfois."},{"t":"Ce tableau définit l'infection tuberculeuse latente","ok":false,"why":"Faux : l'ITL est par définition une PIT asymptomatique."},{"t":"Il s'agit d'une tuberculose pulmonaire commune avec caverne des lobes supérieurs","ok":false,"why":"Faux : la forme commune se présente avec nodules, infiltrats ou cavernes et non avec ce tableau de primo-infection."}],"explanation":"La PIT patente associe parfois AEG, érythème noueux, kérato-conjonctivite phlycténulaire et adénopathies cervicales ; la radiographie montre des adénopathies médiastinales avec ou sans lésion du foyer primaire.","src":"p. 51"},{"id":"p159-qcm-104","type":"QRM","rank":"A","objective":"p159-obj-07","tags":["clinique"],"difficulty":1,"stem":"Un homme de 55 ans en situation de précarité consulte pour une toux avec expectorations depuis 2 mois, un amaigrissement et des sueurs nocturnes. Quels éléments sont habituels dans une tuberculose pulmonaire commune ?","options":[{"t":"Un début insidieux, avec une évolution progressive sur plusieurs semaines à plusieurs mois","ok":true,"why":"Il n'y a pas de symptôme spécifique et l'évolution est progressive."},{"t":"Un fébricule à prédominance nocturne","ok":true,"why":"Il s'associe à l'AEG (asthénie, anorexie, amaigrissement) et aux sueurs nocturnes."},{"t":"Un examen physique pauvre, généralement sans signe spécifique","ok":true,"why":"Les signes physiques sont généralement absents."},{"t":"Une dyspnée aiguë précoce, au premier plan","ok":false,"why":"Faux : la dyspnée est généralement tardive."},{"t":"Un syndrome pleural présent dans tous les cas","ok":false,"why":"Faux : il n'existe qu'en cas de pleurésie tuberculeuse associée."}],"explanation":"Signes généraux (AEG, fébricule nocturne, sueurs nocturnes) et fonctionnels (toux chronique ± expectorations, hémoptysie, dyspnée tardive) sans signe physique spécifique.","src":"p. 52-53"},{"id":"p159-qcm-105","type":"QRM","rank":"A","objective":"p159-obj-08","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Un patient présente une pleurésie à liquide clair, lymphocytaire, avec une suspicion de tuberculose. Quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La biopsie pleurale (histologie et culture) est plus rentable que le liquide seul","ok":true,"why":"La culture est positive dans le liquide ou surtout dans la biopsie pleurale, dont l'histologie montre des granulomes avec nécrose caséeuse."},{"t":"La PCR sur le liquide pleural est presque toujours positive","ok":false,"why":"Faux : la PCR est rarement positive."},{"t":"Il s'agit d'un transsudat","ok":false,"why":"Faux : c'est un exsudat lymphocytaire à liquide clair."},{"t":"Les atteintes pulmonaires associées sont exceptionnelles, la recherche de BAAR dans les crachats est donc inutile","ok":false,"why":"Faux : les atteintes pulmonaires associées sont fréquentes, d'où la bonne rentabilité des recherches de bacilles dans les expectorations."},{"t":"L'histologie pleurale montre typiquement des granulomes sans nécrose","ok":false,"why":"Faux : ce sont des granulomes avec nécrose caséeuse."}],"explanation":"La pleurésie tuberculeuse est un exsudat lymphocytaire à liquide clair, par effraction d'un foyer sous-pleural souvent infra-radiologique ; on fait une biopsie pleurale (histologie et culture) et on cherche aussi les bacilles dans les crachats.","src":"p. 55-57"},{"id":"p159-qcm-106","type":"QRM","rank":"A","objective":"p159-obj-08","tags":["clinique","imagerie"],"difficulty":2,"stem":"Concernant la miliaire tuberculeuse, quelles propositions sont exactes ?","options":[{"t":"Elle résulte d'une dissémination hématogène du bacille","ok":true,"why":"Le bacille passe dans le sang lors de la bacillémie initiale, ou par érosion d'un vaisseau au contact d'un foyer caséeux."},{"t":"La radiographie montre des micronodules diffus des deux poumons, en « grains de mil »","ok":true,"why":"L'aspect est celui d'une pneumopathie interstitielle diffuse micronodulaire touchant l'ensemble des deux poumons."},{"t":"Aux prélèvements respiratoires s'ajoutent des hémocultures sur milieu spécifique et un ECBU adressé en mycobactériologie","ok":true,"why":"La forme est disséminée : on cherche le bacille dans le sang et les urines, voire en myéloculture en cas de leuco-neutropénie."},{"t":"C'est une forme localisée aux lobes supérieurs, avec caverne","ok":false,"why":"Faux : c'est une forme disséminée, généralisée, touchant le poumon et de nombreux autres organes."},{"t":"Elle est habituellement peu symptomatique, d'où un pronostic bénin","ok":false,"why":"Faux : l'altération de l'état général est marquée, souvent fébrile, et la forme est sévère."}],"explanation":"La miliaire est une tuberculose disséminée par voie hématogène, sévère, à l'imagerie micronodulaire diffuse ; tout prélèvement (urines, selles, LCR, biopsie d'organe) doit être envoyé en mycobactériologie.","src":"p. 55, 57"},{"id":"p159-qcm-107","type":"QRM","rank":"A","objective":"p159-obj-09","tags":["diagnostic","paraclinique"],"difficulty":2,"stem":"Devant une suspicion de tuberculose pulmonaire, quelle(s) proposition(s) est (sont) exacte(s) concernant les prélèvements ?","options":[{"t":"Un patient hospitalisé est mis en isolement respiratoire avant les prélèvements","ok":true,"why":"Le patient hospitalisé est placé en chambre seule en isolement respiratoire avant de débuter les prélèvements."},{"t":"La recherche de BAAR est incluse d'office dans un ECBC standard, sans la demander","ok":false,"why":"Faux : elle doit être demandée spécifiquement, un ECBC standard ne la comporte pas."},{"t":"Le tubage gastrique se réalise en fin de journée, après le repas du soir","ok":false,"why":"Faux : il se fait le matin à jeun, avant tout lever, avant la vidange gastrique."},{"t":"Un seul prélèvement négatif à l'examen direct permet d'écarter la tuberculose","ok":false,"why":"Faux : les prélèvements sont multiples et répétés, et un examen direct négatif n'élimine pas le diagnostic."},{"t":"Les prélèvements partent dans un laboratoire de bactériologie standard","ok":false,"why":"Faux : ils sont adressés au laboratoire de mycobactériologie."}],"explanation":"Prélèvements respiratoires systématiques, multiples et répétés, adressés au laboratoire de mycobactériologie ; si le patient ne crache pas : tubage gastrique ; après trois échecs : fibroscopie bronchique avec aspiration.","src":"p. 56-57"},{"id":"p159-qcm-108","type":"QRM","rank":"A","objective":"p159-obj-09","tags":["diagnostic","biologie"],"difficulty":2,"stem":"Concernant la mycobactériologie de la tuberculose, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Un examen direct négatif n'élimine pas le diagnostic","ok":true,"why":"L'examen direct n'est positif qu'au-delà de 10³ bacilles/mL."},{"t":"La culture n'est réalisée que si l'examen direct est positif","ok":false,"why":"Faux : la culture est systématique, même si l'examen direct est négatif."},{"t":"L'antibiogramme est facultatif lorsque la culture est positive","ok":false,"why":"Faux : il est obligatoire et systématique en cas de culture positive."},{"t":"Sur milieu solide de Löwenstein-Jensen, la culture est positive dès 10 à 15 jours","ok":false,"why":"Faux : sur milieu solide la culture est positive à partir de 3 à 4 semaines ; 10 à 15 jours correspondent au milieu liquide."},{"t":"Le test génotypique ne sert qu'une fois le résultat de la culture obtenu","ok":false,"why":"Faux : il permet de ne pas attendre la culture, un test positif pour M. tuberculosis (ex. Xpert® MTB/RIF) suffisant pour affirmer la tuberculose."}],"explanation":"Examen direct (Ziehl-Neelsen, résultat en quelques heures), culture systématique, test génotypique rapide sur tout examen direct ou culture positifs (complexe tuberculosis, gène rpoB), antibiogramme obligatoire.","src":"p. 57"},{"id":"p159-qcm-109","type":"QRM","rank":"A","objective":"p159-obj-10","tags":["imagerie"],"difficulty":2,"stem":"Concernant la radiographie thoracique de la tuberculose pulmonaire commune, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Les lésions siègent généralement dans les segments supérieurs et postérieurs","ok":true,"why":"Nodules, infiltrats et cavernes prédominent aux lobes supérieurs, dans leurs segments supérieurs et postérieurs."},{"t":"Les lésions prédominent aux bases pulmonaires","ok":false,"why":"Faux : elles prédominent aux segments supérieurs et postérieurs."},{"t":"La caverne n'existe pas dans la forme commune","ok":false,"why":"Faux : la caverne (lésion excavée) est l'un des trois types de lésions, avec les nodules et les infiltrats."},{"t":"L'aspect habituel est une pneumopathie interstitielle diffuse micronodulaire des deux poumons","ok":false,"why":"Faux : c'est l'aspect de la miliaire tuberculeuse, forme disséminée."},{"t":"Une radiographie normale élimine la tuberculose, même chez un patient VIH très immunodéprimé","ok":false,"why":"Faux : chez un patient VIH avec des CD4 très bas, la radiographie peut être quasi normale."}],"explanation":"Forme commune : nodules, infiltrats et cavernes (isolés ou associés) des segments supérieurs et postérieurs. Miliaire : micronodules diffus bilatéraux en grains de mil.","src":"p. 53, 55, 65"},{"id":"p159-qcm-110","type":"QRM","rank":"A","objective":"p159-obj-05","tags":["diagnostic"],"difficulty":2,"stem":"Concernant l'interprétation de l'IDR à la tuberculine, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Elle peut être négative (anergie tuberculinique) chez un patient immunodéprimé","ok":true,"why":"L'immunodépression peut négativer l'IDR, d'où le terme d'anergie tuberculinique."},{"t":"Elle est facile à interpréter dans les 10 ans qui suivent une vaccination par le BCG","ok":false,"why":"Faux : l'interprétation est difficile pendant les 10 ans qui suivent le BCG."},{"t":"Elle est spécifique de M. tuberculosis et ne réagit jamais avec le BCG","ok":false,"why":"Faux : elle réagit aussi avec M. bovis (donc le BCG) et certaines mycobactéries atypiques."},{"t":"On retient le diamètre de l'érythème comme critère de lecture","ok":false,"why":"Faux : on mesure l'induration et on ne tient pas compte de l'érythème."},{"t":"Une IDR positive permet de distinguer une ITL d'une tuberculose maladie","ok":false,"why":"Faux : aucun des deux tests (IDR, IGRA) ne distingue ITL et tuberculose maladie."}],"explanation":"IDR : 0,1 mL de tuberculine en intradermique, lecture à 72 h de l'induration ; test non spécifique (réactions croisées avec le BCG), possible anergie chez l'immunodéprimé, interprétation selon les antécédents et le statut vaccinal.","src":"p. 62"},{"id":"p159-qcm-111","type":"QRM","rank":"A","objective":"p159-obj-05","tags":["diagnostic","biologie"],"difficulty":2,"stem":"Concernant les tests IGRA, quelles propositions sont exactes ?","options":[{"t":"Ils mesurent la production d'interféron γ par les lymphocytes face à des antigènes spécifiques de M. tuberculosis","ok":true,"why":"C'est le principe du QuantiFERON-TB Gold IT et du T-SPOT.TB."},{"t":"Ils se font sur une simple prise de sang et ne dépendent pas de l'opérateur","ok":true,"why":"La réalisation est facile, en une seule visite, avec une interprétation rapide."},{"t":"Ils ne croisent pas avec le BCG et donnent moins de faux positifs que l'IDR","ok":true,"why":"Leurs antigènes sont spécifiques de M. tuberculosis."},{"t":"Ils permettent de distinguer une ITL d'une tuberculose maladie","ok":false,"why":"Faux : IDR et IGRA ne distinguent pas ITL et tuberculose maladie."},{"t":"Un résultat négatif permet d'éliminer une tuberculose active","ok":false,"why":"Faux : ces tests ne servent pas à diagnostiquer ni à éliminer une tuberculose active, seulement à diagnostiquer une ITL."}],"explanation":"L'IGRA, comme l'IDR, ne sert qu'au diagnostic d'ITL, après élimination d'une tuberculose maladie par l'examen clinique et la radiographie ; son résultat peut être positif, négatif ou indéterminé.","src":"p. 62-63"},{"id":"p159-qcm-112","type":"QRM","rank":"A","objective":"p159-obj-05","tags":["prévention","diagnostic"],"difficulty":2,"stem":"Avant l'introduction d'un traitement par anti-TNFα, quelles propositions sont exactes ?","options":[{"t":"Le test IGRA est préféré à l'IDR pour dépister une ITL","ok":true,"why":"Avant anti-TNFα, on réalise interrogatoire, examen clinique, radiographie et un test IGRA, préféré à l'IDR."},{"t":"En cas d'ITL, la chimioprophylaxie INH + RMP de 3 mois doit débuter au moins 3 semaines avant l'anti-TNFα","ok":true,"why":"L'ITL est traitée quel que soit son délai, au moins 3 semaines avant le début de l'anti-TNFα."},{"t":"Si la tuberculose est active, l'anti-TNFα attend la fin des 2 mois de quadrithérapie (phase d'attaque)","ok":true,"why":"On ne met en route l'anti-TNFα qu'une fois la phase d'attaque terminée."},{"t":"L'IDR est préférée à l'IGRA","ok":false,"why":"Faux : c'est l'IGRA qui est préféré à l'IDR."},{"t":"En cas d'ITL, l'anti-TNFα peut être débuté le jour même de la chimioprophylaxie","ok":false,"why":"Faux : la chimioprophylaxie doit débuter au moins 3 semaines avant l'anti-TNFα."}],"explanation":"Les anti-TNF augmentent nettement l'incidence de la tuberculose : bilan préalable avec IGRA, chimioprophylaxie en cas d'ITL, report de l'anti-TNFα en cas de tuberculose active.","src":"p. 65"},{"id":"p159-qcm-113","type":"QRM","rank":"A","objective":"p159-obj-12","tags":["traitement"],"difficulty":2,"stem":"Concernant les principes du traitement antituberculeux, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Une polyantibiothérapie est obligatoire (risque de mutants résistants)","ok":true,"why":"La monothérapie expose à des mutants résistants, et il faut agir sur les 3 populations de bacilles."},{"t":"Une monothérapie par isoniazide suffit si le patient est parfaitement observant","ok":false,"why":"Faux : la monothérapie est proscrite dans la tuberculose maladie (risque de mutants résistants)."},{"t":"La durée de 6 mois s'applique aussi à la forme neuro-méningée de l'adulte","ok":false,"why":"Faux : la forme neuro-méningée est traitée 9 à 12 mois."},{"t":"Le temps de doublement long du bacille impose plusieurs prises quotidiennes","ok":false,"why":"Faux : le temps de doublement long (20 h) permet une prise unique quotidienne."},{"t":"L'observance devient secondaire dès que la quadrithérapie est débutée","ok":false,"why":"Faux : l'observance est capitale pour limiter les rechutes et l'émergence de souches résistantes."}],"explanation":"Principes : prise unique quotidienne, traitement prolongé (bacilles persistants), polyantibiothérapie obligatoire, observance capitale avec l'appui du CLAT, adaptation à l'antibiogramme.","src":"p. 60"},{"id":"p159-qcm-114","type":"QRM","rank":"A","objective":"p159-obj-12","tags":["traitement","physiopathologie"],"difficulty":3,"stem":"Concernant les populations de bacilles et les antituberculeux actifs sur elles, quelles propositions sont exactes ?","options":[{"t":"Les bacilles extracellulaires (95 %), responsables de la contagiosité et des symptômes, sont sensibles à l'isoniazide et à la rifampicine","ok":true,"why":"C'est la population majoritaire, responsable de la contagiosité et de la symptomatologie."},{"t":"Les bacilles intracellulaires quiescents des macrophages sont sensibles au pyrazinamide et à la rifampicine","ok":true,"why":"Le PZA et la RMP agissent sur les bacilles quiescents situés dans les macrophages."},{"t":"Les bacilles extracellulaires du caséum, responsables du risque de rechute, sont sensibles à la rifampicine","ok":true,"why":"Seule la rifampicine est active sur cette population, d'où le risque de rechute à distance."},{"t":"Les bacilles intracellulaires quiescents ne sont sensibles qu'à l'isoniazide","ok":false,"why":"Faux : ils sont sensibles au pyrazinamide et à la rifampicine."},{"t":"Les bacilles du caséum sont sensibles à l'isoniazide et au pyrazinamide","ok":false,"why":"Faux : seule la rifampicine est citée comme active sur les bacilles du caséum."}],"explanation":"La rifampicine est citée pour les trois populations ; la polyantibiothérapie est obligatoire pour agir sur les 3 populations de bacilles et éviter l'émergence de mutants résistants.","src":"p. 59"},{"id":"p159-qcm-115","type":"QRM","rank":"A","objective":"p159-obj-14","tags":["traitement"],"difficulty":2,"stem":"Concernant la rifampicine, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"Elle rend la pilule œstro-progestative inefficace","ok":true,"why":"Puissant inducteur enzymatique, elle impose de changer de mode de contraception (contraception mécanique seule possible)."},{"t":"Son principal effet indésirable est la névrite optique rétrobulbaire","ok":false,"why":"Faux : c'est l'effet indésirable de l'éthambutol."},{"t":"Elle est contre-indiquée en cas d'insuffisance rénale","ok":false,"why":"Faux : la contre-indication en cas d'insuffisance hépatocellulaire et rénale concerne le pyrazinamide."},{"t":"Son absorption est améliorée lorsqu'on la prend pendant le repas","ok":false,"why":"Faux : le repas diminue l'absorption ; la RMP se prend à jeun."},{"t":"La coloration orange des urines impose d'arrêter le traitement","ok":false,"why":"Faux : cette coloration est un phénomène normal, non un effet secondaire, à annoncer au patient."}],"explanation":"RMP : inducteur enzymatique (AVK avec surveillance de l'INR, anticoagulants oraux directs, pilule, certains antirétroviraux, méthadone, corticoïdes, digitaliques), réactions immuno-allergiques, coloration orange des larmes, du sperme et des urines.","src":"p. 59-61"},{"id":"p159-qcm-116","type":"QRM","rank":"A","objective":"p159-obj-14","tags":["traitement","suivi"],"difficulty":2,"stem":"Sous traitement antituberculeux, quelles propositions sont exactes concernant la surveillance hépatique ?","options":[{"t":"Le bilan hépatique est hebdomadaire pendant le premier mois","ok":true,"why":"Il est hebdomadaire le premier mois, puis le rythme dépend du terrain."},{"t":"Entre 3 et 5 N, on arrête le pyrazinamide et on poursuit INH + RMP + EMB","ok":true,"why":"On poursuit une trithérapie (2 mois de trithérapie puis 7 mois de bithérapie)."},{"t":"Au-delà de 5 N, on arrête l'isoniazide et le pyrazinamide","ok":true,"why":"Une réintroduction de l'INH à demi-dose est possible après normalisation ; en cas de signe de gravité ou de cytolyse majeure, on arrête tout."},{"t":"Au-delà de 5 N, on arrête uniquement la rifampicine","ok":false,"why":"Faux : on arrête l'isoniazide et le pyrazinamide."},{"t":"En dessous de 3 N, on arrête tous les antituberculeux par précaution","ok":false,"why":"Faux : en dessous de 3 N, on met en place une surveillance rapprochée jusqu'à normalisation."}],"explanation":"Surveillance des transaminases (INH hépatite, PZA cytolyse plus tardive) : < 3 N surveillance rapprochée ; 3-5 N arrêt du PZA ; > 5 N arrêt de l'INH et du PZA ; en cas de gravité, arrêt de tous les antituberculeux et avis spécialisé.","src":"p. 59, 61"},{"id":"p159-qcm-117","type":"QRM","rank":"B","objective":"p159-obj-14","tags":["traitement","grossesse"],"difficulty":2,"stem":"Une femme enceinte doit être traitée pour une tuberculose pulmonaire. Quelles propositions sont exactes ?","options":[{"t":"Le schéma thérapeutique est le même que hors grossesse","ok":true,"why":"Il n'y a pas de tératogénicité connue pour INH, RMP, EMB et PZA."},{"t":"L'isoniazide impose de supplémenter la mère en vitamine B6","ok":true,"why":"La vitamine B6 prévient la polyneuropathie sous INH."},{"t":"En cas de rifampicine au dernier trimestre, on prescrit de la vitamine K1","ok":true,"why":"Il existe un risque d'hémorragie maternelle et néonatale précoce."},{"t":"Le pyrazinamide est contre-indiqué pendant toute la grossesse","ok":false,"why":"Faux : aucun des quatre médicaments de première ligne n'est tératogène connu."},{"t":"L'éthambutol est tératogène et doit être remplacé","ok":false,"why":"Faux : l'éthambutol n'a pas de tératogénicité connue."}],"explanation":"Chez la femme enceinte, le schéma est identique à celui de l'adulte hors grossesse, avec vitamine B6 sous INH et vitamine K1 si RMP au dernier trimestre ; allaitement non conseillé sous EMB et PZA, à discuter au cas par cas.","src":"p. 64"},{"id":"p159-qcm-118","type":"QRM","rank":"A","objective":"p159-obj-15","tags":["prévention"],"difficulty":2,"stem":"Concernant l'enquête autour d'un cas de tuberculose, quelles propositions sont exactes ?","options":[{"t":"Le dépistage systématique concerne les contacts étroits ou réguliers","ok":true,"why":"Les contacts occasionnels ne sont pas dépistés systématiquement."},{"t":"La période de contagiosité à considérer est celle des 3 mois précédant le diagnostic","ok":true,"why":"Un patient contagieux au diagnostic l'est en général depuis 3 mois."},{"t":"Le test IGRA ou IDR de diagnostic de l'ITL est fait 8 semaines après le dernier contact","ok":true,"why":"Le dépistage d'une éventuelle tuberculose maladie (clinique, radiographie) se fait lui dès que possible."},{"t":"Les contacts occasionnels (un dîner) sont dépistés systématiquement","ok":false,"why":"Faux : seuls les contacts étroits ou réguliers le sont."},{"t":"Le risque d'infection est indépendant de la contagiosité du cas index","ok":false,"why":"Faux : il dépend de la contagiosité du cas (examen direct positif, cavités sur la radiographie), de la période de contagiosité et de la proximité."}],"explanation":"Le signalement nominatif au CLAT déclenche l'enquête : examen clinique, évaluation des risques et radiographie dès que possible, puis test IGRA ou IDR à 8 semaines du dernier contact ; chimioprophylaxie des ITL et traitement précoce des tuberculoses dépistées.","src":"p. 62, 66"},{"id":"p159-qcm-119","type":"QRM","rank":"A","objective":"p159-obj-15","tags":["prévention","traitement"],"difficulty":2,"stem":"Dans quelles situations propose-t-on de rechercher et de traiter une infection tuberculeuse latente ?","options":[{"t":"ITL récente (moins de 2 ans), repérée lors de l'enquête autour d'un cas","ok":true,"why":"Ce sont en pratique les contacts identifiés par le CLAT."},{"t":"ITL avant la mise en place d'un traitement immunosuppresseur (anti-TNFα, greffe)","ok":true,"why":"L'ITL est dépistée et traitée avant l'immunosuppression."},{"t":"ITL diagnostiquée à l'occasion de la découverte d'une séropositivité pour le VIH","ok":true,"why":"Le dépistage de l'ITL est systématique dans le bilan initial d'un patient VIH."},{"t":"ITL chez un migrant de moins de 18 ans arrivé depuis moins de 5 ans d'un pays de forte incidence","ok":true,"why":"Cette situation figure parmi les ITL auxquelles un traitement est proposé."},{"t":"ITL ancienne chez un adulte immunocompétent sans autre facteur de risque","ok":false,"why":"Faux : chez l'adulte, la chimioprophylaxie est proposée en cas de facteur de risque d'évolution rapide (immunodépression, ITL récente)."}],"explanation":"On traite les ITL à haut risque d'évolution vers la tuberculose maladie : INH seul 6 mois ou INH + RMP 3 à 4 mois, avec les mêmes précautions et la même surveillance que pour une tuberculose maladie.","src":"p. 61-63"},{"id":"p159-qcm-120","type":"QRM","rank":"A","objective":"p159-obj-07","tags":["clinique","diagnostic"],"difficulty":2,"stem":"Concernant la tuberculose chez le patient infecté par le VIH, quelle(s) proposition(s) est (sont) exacte(s) ?","options":[{"t":"La tuberculose classe le patient VIH au stade SIDA","ok":true,"why":"La survenue d'une tuberculose fait passer le patient VIH au stade SIDA."},{"t":"Le risque de tuberculose est identique à celui de la population générale","ok":false,"why":"Faux : il est multiplié par 7 chez le patient VIH."},{"t":"En dessous de 200 CD4/mm³, le granulome tuberculeux est abondant et typique","ok":false,"why":"Faux : sans immunité cellulaire, il n'y a pas de processus granulomateux."},{"t":"Au-dessus de 350 CD4/mm³, les formes sont toujours atypiques","ok":false,"why":"Faux : au-dessus de 350 CD4/mm³, les symptômes sont ceux de la tuberculose pulmonaire classique."},{"t":"La radiographie est toujours très évocatrice, quel que soit le taux de CD4","ok":false,"why":"Faux : elle peut être quasi normale quand les CD4 sont très bas."}],"explanation":"Chez le patient VIH : risque multiplié par 7, stade SIDA ; avec moins de 200 CD4, haut risque de passage de l'ITL à la tuberculose maladie, fièvre souvent isolée, atteintes extra-respiratoires à rechercher systématiquement.","src":"p. 65"}],"edn":[],"trees":[],"treatments":{"data":[],"strategies":[]},"cases":[],"ecg":{"data":[],"method":""},"echo":{"data":[]},"flash":null,"pareto":{"id":"p159-pareto","points":[{"id":"p159-par-01","rank":"A","cat":"clinique","text":"TB pulmonaire commune : AEG, fébricule et sueurs **nocturnes**, toux ± hémoptysie, examen physique **pauvre** ; Rx = **nodules + infiltrats + cavernes** des **lobes supérieurs**","src":"p. 50, 52-53"},{"id":"p159-par-02","rank":"A","cat":"examen","text":"Diagnostic de certitude = mise en évidence du **BK** : prélèvements **multiples**, recherche de **BAAR** à demander (pas sur ECBC standard) ; pas de crachat → **tubage gastrique** à jeun","src":"p. 56"},{"id":"p159-par-03","rank":"A","cat":"piège","text":"**ED négatif n'élimine pas** la TB (positif si > 10³ bacilles/mL) → **culture** systématique (solide 3-4 sem, liquide 10-15 j) + test génotypique (**rpoB** = RMP) + **antibiogramme**","src":"p. 57"},{"id":"p159-par-04","rank":"A","cat":"traitement","text":"TTT standard **6 mois** : **INH+RMP+EMB+PZA 2 mois** puis **INH+RMP 4 mois** ; neuro-méningée **9-12 mois** ; pas de monothérapie, observance capitale","src":"p. 50, 60"},{"id":"p159-par-05","rank":"A","cat":"traitement","text":"**RMP** : inducteur enzymatique (AVK → INR, **pilule inefficace**), sécrétions **oranges** ; **EMB** : névrite optique ; **PZA** : hyperuricémie, CI si IH/IR ; **INH** : polynévrite (B6), hépatite","src":"p. 59"},{"id":"p159-par-06","rank":"A","cat":"suivi","text":"Bilan hépatique **hebdomadaire le 1er mois** ; transaminases 3-5 N → arrêt du **PZA** ; > 5 N → arrêt **INH + PZA** ; bilan initial avec sérologie **VIH** ; vision des couleurs sous EMB","src":"p. 60-61"},{"id":"p159-par-07","rank":"A","cat":"définition","text":"**PIT** le plus souvent asymptomatique = **ITL** ; **10 %** font une TM, surtout dans les **2 ans** ; risque ↑ : **VIH**, anti-TNF/immunosuppresseurs, âges extrêmes, diabète, précarité","src":"p. 50-52"},{"id":"p159-par-08","rank":"A","cat":"examen","text":"**IDR** : 0,1 mL intradermique, lecture à **72 h** (induration) ; positive ≥ **5 mm** ; ITL si > **10 mm** (non vacciné) ou > **15 mm** (BCG) ou virage > 10 mm à 3 mois","src":"p. 62"},{"id":"p159-par-09","rank":"A","cat":"piège","text":"IDR et IGRA **ne distinguent pas ITL et TM** : ils servent à dépister l'**ITL** ; **IGRA** = interféron γ, pas de réaction croisée **BCG** ; avant **anti-TNF** → IGRA préféré","src":"p. 62-63, 65"},{"id":"p159-par-10","rank":"A","cat":"prévention","text":"Isolement respiratoire en chambre seule dès les prélèvements ; levé après **15 jours** de TTT si ED négatif ; patient contagieux depuis **3 mois** au diagnostic","src":"p. 56, 61"},{"id":"p159-par-11","rank":"A","cat":"prévention","text":"Contacts **étroits/réguliers** (**CLAT**) : examen + Rx dès que possible, IGRA/IDR à **8 sem** du dernier contact ; ITL traitée par INH **6 mois** ou INH+RMP **3-4 mois**","src":"p. 62-63, 66"},{"id":"p159-par-12","rank":"A","cat":"prévention","text":"**DO** : TB confirmée ou suspectée dès le début du TTT → **ARS** (anonyme) + signalement nominatif **CLAT** ; ITL de moins de **18 ans** à déclarer","src":"p. 66"},{"id":"p159-par-13","rank":"A","cat":"clinique","text":"**Miliaire** : dissémination **hématogène**, AEG marquée, micronodules diffus en **grains de mil** ; pleurésie TB = exsudat **lymphocytaire**, biopsie pleurale","src":"p. 55-56"},{"id":"p159-par-14","rank":"A","cat":"gravité","text":"**VIH** : TB = stade **SIDA**, risque ×**7** ; **CD4 < 200** : souvent seule la **fièvre**, Rx quasi normale ; éviter les **fluoroquinolones** si suspicion de TB (négativent les prélèvements)","src":"p. 59-60, 65"},{"id":"p159-par-15","rank":"A","cat":"prévention","text":"**BCG** : plus obligatoire, recommandé **< 15 ans** à risque (Guyane, Mayotte, IdF) ; **intradermique**, sans IDR préalable ; CI : **VIH** et immunodépression ; immunité 10-15 ans","src":"p. 64"}]},"extra":{"semio":[],"criteres":[],"chiffres":[],"physio":[],"parcours":[],"examens":[]}});
